import type { ReactNode } from 'react';
import './bento-grid.css';

export interface BentoGridProps {
  children: ReactNode;
  /** Columns at full width: 3 or 4. The grid drops to 2 and then 1 as its container narrows. */
  columns?: 3 | 4;
  label?: string;
  className?: string;
}

export interface BentoItemProps {
  children: ReactNode;
  /** Columns to span at full width (capped as the grid narrows). */
  colSpan?: 1 | 2 | 3 | 4;
  /** Rows to span. */
  rowSpan?: 1 | 2;
  /** `raised` uses the second surface tint, for the item you want seen first. */
  tone?: 'plain' | 'raised';
  className?: string;
}

/**
 * A spanning grid that re-flows with its container, not the viewport, so it works the same
 * in a sidebar as on a full page. Reading order always follows source order.
 */
export function BentoGrid({ children, columns = 4, label, className }: BentoGridProps) {
  return (
    <div
      className={['atl-bento', className].filter(Boolean).join(' ')}
      role={label ? 'group' : undefined}
      aria-label={label}
    >
      <div className="atl-bento__grid" data-columns={columns}>
        {children}
      </div>
    </div>
  );
}

export function BentoItem({
  children,
  colSpan = 1,
  rowSpan = 1,
  tone = 'plain',
  className,
}: BentoItemProps) {
  return (
    <div
      className={['atl-bento__item', className].filter(Boolean).join(' ')}
      data-col={colSpan}
      data-row={rowSpan}
      data-tone={tone}
    >
      {children}
    </div>
  );
}

@layer atlas.components {
  .atl-bento {
    container-type: inline-size;
    width: 100%;
  }

  .atl-bento__grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-auto-rows: minmax(8rem, auto);
    grid-auto-flow: dense;
    gap: var(--space-s);
  }

  .atl-bento__grid[data-columns='3'] {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .atl-bento__item {
    min-width: 0;
    padding: var(--space-m);
    border-radius: var(--radius-panel);
    background: var(--shoal);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 45%, transparent);
  }

  .atl-bento__item[data-tone='raised'] {
    background: var(--reef);
  }

  .atl-bento__item[data-col='2'] {
    grid-column: span 2;
  }
  .atl-bento__item[data-col='3'] {
    grid-column: span 3;
  }
  .atl-bento__item[data-col='4'] {
    grid-column: span 4;
  }
  .atl-bento__item[data-row='2'] {
    grid-row: span 2;
  }

  .atl-bento__grid[data-columns='3'] .atl-bento__item[data-col='4'] {
    grid-column: span 3;
  }

  /* Medium containers: two columns, wide items span both. */
  @container (width < 44rem) {
    .atl-bento__grid,
    .atl-bento__grid[data-columns='3'] {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .atl-bento__grid .atl-bento__item:is([data-col='3'], [data-col='4']) {
      grid-column: span 2;
    }
  }

  /* Narrow containers: one column, in source order. */
  @container (width < 26rem) {
    .atl-bento__grid,
    .atl-bento__grid[data-columns='3'] {
      grid-template-columns: minmax(0, 1fr);
      grid-auto-flow: row;
    }
    .atl-bento__grid .atl-bento__item {
      grid-column: auto;
      grid-row: auto;
    }
  }
}
